# Now let's build the output grid by applying the transformation rule
# A cell becomes 8 if it's inside a region that's at least 3x3

def create_output():
    result = [[2]*28 for _ in range(27)]

    # Region 1 (val=1): rows 2-8, cols 4-6 (height=7, width=3)
    # Interior: rows 3-7, col 5
    for r in range(3, 8):
        result[r][5] = 8

    # Region 2 (val=7): rows 5-8, cols 16-22 (height=4, width=7)
    # Interior: rows 6-7, cols 17-21
    for r in range(6, 8):
        for c in range(17, 22):
            result[r][c] = 8

    # Region 3 (val=4): rows 11-17, cols 24-26 (height=7, width=3)
    # Interior: rows 12-16, col 25
    for r in range(12, 17):
        result[r][25] = 8

    # Region 4 (val=0): rows 14-17, cols 16-22 (height=4, width=7)
    # Interior: rows 15-16, cols 17-21
    for r in range(15, 17):
        for c in range(17, 22):
            result[r][c] = 8

    # Region 5 (val=3): rows 18-22, cols 4-10 (height=5, width=7)
    # Interior: rows 19-21, cols 5-9
    for r in range(19, 22):
        for c in range(5, 10):
            result[r][c] = 8

    # Region 6 (val=9): rows 18-23, cols 20-26 (height=6, width=7)
    # Interior: rows 19-22, cols 21-25
    for r in range(19, 23):
        for c in range(21, 26):
            result[r][c] = 8

    # Region 7 (val=5): rows 21-25, cols 16-19 (height=5, width=4)
    # Interior: rows 22-24, cols 17-18
    for r in range(22, 25):
        for c in range(17, 19):
            result[r][c] = 8

    return result

output_grid = create_output()
for row in output_grid:
    print(' '.join(map(str, row)))

